#!/usr/bin/env python3
"""What's new in v1.4.1: real in-game screenshots from the v1.4.1 ROM itself (r09, 115a3204...), mGBA 0.10.5 engine
-> data/whatsnew-v1.4.1.json + site/assets/game/whatsnew/v1.4.1/.  usage: whatsnew_v141.py --workspace <VSC>"""
import argparse, hashlib, json, shutil
from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent
ap = argparse.ArgumentParser(); ap.add_argument("--workspace", default=str(ROOT.parent)); a = ap.parse_args(); WS = Path(a.workspace)
sha = lambda p: hashlib.sha256(Path(p).read_bytes()).hexdigest()
R09 = "115a3204c1b2ff8bff6b39fb89418fd80b7674172b5c97974f7b7da8fd806d58"; R04 = "0bc3464580952c6d7b41b0e7755f1d0cb35d5fceb1c388105c4fc460628f1a2a"
assert sha(WS / "output/project-blonde-v1.4.1-20261031/Pokemon - Project Blonde.gba") == R09
E_ = "output/v1.4-exp-portable-pc-20261031/c3/evidence"
SHOTS = [("party", f"{E_}/pub-party.png", "Press R on the party screen", "START, POKéMON: the new R◆PC hint sits beside SEL◆ORDER. Press R to open Pokémon Storage."),
         ("storage", f"{E_}/pub-storage.png", "Your boxes, anywhere", "The same Pokémon Storage as a Pokémon Center PC. Close it and you are back on the party screen."),
         ("move", f"{E_}/pub-party-menu.png", "Deposit and withdraw", "Move Pokémon between your party and your boxes, read their summaries and rearrange your boxes. HP, PP and status conditions stay as they are."),
         ("frontier", f"{E_}/frontier-center-party.png", "Battle Frontier", "It works in the Frontier’s Pokémon Center, Mart, Lounges and outdoor areas, and not during a challenge."),
         ("challenge", f"{E_}/fr-813-pike-first-seven-choices.png", "Where it is off", "In the Battle Pike and other special challenges the hint is gone and the party screen works as usual.")]
out = ROOT / "site/assets/game/whatsnew/v1.4.1"; out.mkdir(parents=True, exist_ok=True); rows = []
from PIL import Image
for i, f, t, c in SHOTS:
    src = WS / f; dst = out / f"{i}.png"; shutil.copyfile(src, dst); assert Image.open(dst).size == (240, 160)
    rows.append({"id": i, "file": dst.name, "title": t, "caption": c, "source": f, "sha256": sha(dst)})
title = ROOT / "site/assets/game/title/title-v1.4.png"; dst = ROOT / "site/assets/game/title/title-v1.4.1.png"; shutil.copyfile(title, dst)
G = {"_about": "Generated by tools/whatsnew_v141.py - do not edit. Screenshots taken on the v1.4.1 ROM itself (r09), mGBA 0.10.5 engine. The title screen of v1.4.1 still shows v1.4 by owner decision, so the v1.4 title picture is correct.",
     "kind": "story", "before": {"public": "v1.4", "build": "r04", "sha256": R04}, "after": {"public": "v1.4.1", "build": "r09", "sha256": R09}, "screenshots_from": {"build": "r09", "sha256": R09},
     "heading": "The portable Pokémon PC", "lead": "Press R on the party screen to open Pokémon Storage without walking back to a Pokémon Center.",
     "link": ["/features/portable-pc/", "How the portable PC works"], "desc": "the portable Pokémon PC: press R on the party screen to open Pokémon Storage",
     "title": {"file": dst.name, "source": "site/assets/game/title/title-v1.4.png", "sha256": sha(dst)}, "shots": rows}
(ROOT / "data/whatsnew-v1.4.1.json").write_text(json.dumps(G, indent=1, ensure_ascii=False) + "\n"); print(len(rows), "shots")
